import { capitalize, routeName } from '../paths';
import type { ApiMethod } from '../server/types';
import type { DetectedEndpoint, ServedEndpoints } from './detect';

/** An API file with its URL and what it serves. */
export interface ApiFile extends Omit<ServedEndpoints, 'warnings'> {
  /** Path relative to the app directory, e.g. `modules/shop/api/products.$id.ts`. */
  file: string;
  /** Full URL pattern in endpoint-kit syntax, e.g. `/api/shop/products/:id`. */
  path: string;
  warnings?: string[];
}

/** One route of the generated file. */
export interface GeneratedRoute {
  name: string;
  method: ApiMethod;
  path: string;
  file: string;
}

/** Options for {@link generateRoutesCode}. */
export interface CodeOptions {
  /** Import path of each API file from the client file, without extension. */
  importPath: (file: string) => string;
  /** URL prefix, left out of route names. */
  prefix?: string;
  /** Name of the exported routes object. Defaults to `routes`. */
  routesName?: string;
  /** Server file: import paths of API files and of the client file from it. */
  server?: { importPath: (file: string) => string; clientImport: string };
}

/** Result of {@link generateRoutesCode}. */
export interface CodeResult {
  /** The client routes file (type-only imports of API files). */
  code: string;
  /** The server file (`localFetch` calling handlers in-process), when requested. */
  serverCode?: string;
  routes: GeneratedRoute[];
  warnings: string[];
}

const HEADER = '// Generated by auto-types-api. Do not edit by hand.';

/** Generates the routes file for endpoint-kit and, optionally, the server file. */
export function generateRoutesCode(files: readonly ApiFile[], options: CodeOptions): CodeResult {
  const routesName = options.routesName ?? 'routes';
  const warnings: string[] = [];
  const imports: string[] = [];
  const serverImports: string[] = [];
  const entries: string[] = [];
  const handlers: string[] = [];
  const routes: GeneratedRoute[] = [];
  const names = new Set<string>();

  for (const api of files) {
    for (const warning of api.warnings ?? []) warnings.push(`${api.file}: ${warning}`);
    if (api.endpoints.length === 0) {
      warnings.push(
        `${api.file}: no api.serve({ GET, POST, ... }) found, skipped (see auto-types-api README)`,
      );
      continue;
    }
    if (api.path.includes('*')) {
      warnings.push(
        `${api.file}: splat route "${api.path}" cannot be filled by endpoint-kit clients; call it with a full path instead`,
      );
    }
    const alias = `api${String(imports.length)}`;
    imports.push(`import type * as ${alias} from ${quote(options.importPath(api.file))};`);
    serverImports.push(
      `import { ${api.handler} as ${alias} } from ${quote(options.server?.importPath(api.file) ?? '')};`,
    );

    for (const endpoint of api.endpoints) {
      const { method } = endpoint;
      const base = routeName(method, api.path, options.prefix);
      let name = base;
      for (let n = 2; names.has(name); n++) name = `${base}${String(n)}`;
      if (name !== base) warnings.push(`${api.file}: route name "${base}" taken, using "${name}"`);
      names.add(name);

      routes.push({ name, method, path: api.path, file: api.file });
      entries.push(
        `  /** ${method} ${api.path} (${api.file}) */\n` +
          `  ${name}: createRoute.${method.toLowerCase()}(${quote(api.path)}, clientOptions<typeof ${alias}.${api.handler}, '${method}'>(${staticOptions(endpoint)})),`,
      );
      handlers.push(`  ${name}: ${alias},`);
    }
  }

  const code = [
    HEADER,
    "import { createRoute } from 'endpoint-kit';",
    "import { clientOptions } from 'auto-types-api/client';",
    ...imports,
    '',
    `export const ${routesName} = {`,
    ...entries,
    '};',
    '',
    `export type ${capitalize(routesName)} = typeof ${routesName};`,
    '',
  ].join('\n');

  const serverCode =
    options.server &&
    [
      HEADER,
      '// Server only: imports every API handler. Use localFetch in loaders to call them in-process.',
      "import { createLocalFetch } from 'auto-types-api';",
      `import { ${routesName} } from ${quote(options.server.clientImport)};`,
      ...serverImports,
      '',
      'export const handlers = {',
      ...handlers,
      '};',
      '',
      `export const localFetch = createLocalFetch(${routesName}, handlers);`,
      '',
    ].join('\n');

  return { code, ...(serverCode ? { serverCode } : {}), routes, warnings };
}

/** The runtime options argument of `clientOptions(...)`, empty when all are defaults. */
function staticOptions({ bodyType, responseType, errors }: DetectedEndpoint): string {
  const parts: string[] = [];
  if (bodyType) parts.push(`bodyType: '${bodyType}'`);
  if (responseType) parts.push(`responseType: '${responseType}'`);
  if (errors?.length) parts.push(`errors: [${errors.join(', ')}]`);
  return parts.length ? `{ ${parts.join(', ')} }` : '';
}

function quote(value: string): string {
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}
